/* EDIT THE “MAIN COLORS” BELOW TO APPLY YOUR ORGANISATION’S COLORS */
/* Add your primary, secondary and tertiary colours by typing colour names such as "white" etc. or by replacing the hex color codes below. */
:root {
  --primary-palette-colour: #E66C18;
  --secondary-palette-colour: #00122D;
  --primary-font-colour: #FFFFFF;
  --secondary-font-colour: #0066A4;
}

/* No need to touch the code below*/
#slides-view, #slides-view-inner, #lesson-menu {
  color: var(--secondary-font-colour) !important;
  background-color: var(--secondary-palette-colour) !important;
}
/*/ Buttons /*/
.btn.btn-muted,
.btn.btn-solid,
.btn.btn-primary {
  background: var(--primary-palette-colour);
  color: var(--primary-font-colour);
}
.btn.btn-muted.__active,
.btn.btn-muted:hover,
.btn.btn-solid.__active,
.btn.btn-solid:hover,
.btn.btn-primary__active,
.btn.btn-primary:hover {
  background: var(--primary-palette-colour);
  color: var(--primary-font-colour);
  filter: brightness(90%);
}
/* exclude game memory */
.slide-game-memory .game-tiles .btn.btn-solid {
  background: var(--primary-palette-colour);
  color: var(--primary-font-colour);
}
/*/ Header & Slides /*/
/*/ Corner Box /*/
#lesson-header-nav {
  background: #00000040;
  color: #fff;
}
/*/ Menu Button /*/
#lesson-header-nav-menu-btn {
  border-left: 1px solid var(--secondary-palette-colour);
}
/*/ Line at the Top/*/
#lesson-header-title-content {
  border-bottom: 1px solid var(--secondary-font-colour);
  color: var(--secondary-font-colour);
}
/*/ Progress Bar /*/
#indicator {
  background-color: #00000040;
  color: var(--primary-palette-colour);
}
/*/ Line at the bottom/*/
#slides {
  border-bottom: 1px solid var(--secondary-font-colour);
}
/*/ Image Background Color When You Zoom in/*/
.pswp__item {
  background: var(--primary-palette-colour);
}

/*/----- Multiple Choice Slides ------/*/
/*/Multiple Choice Slides Selected Button/*/
.selectable.active .btn {
  background-color: var(--secondary-palette-colour);
  color: var(--secondary-font-colour);
}
/*/Multiple Choice Incorrect/*/
.slide-multiple-choice-game.state-complete .selectable.incorrect .btn {
  background: var(--secondary-palette-colour);
  color: var(--secondary-font-colour);
}
/*/Multiple Choice Correct/*/
.slide-multiple-choice-game.state-complete .selectable.correct .btn {
  background: var(--primary-palette-colour);
  color: var(--primary-font-colour);
}
/*/-----------------------------------/*/

/*/Chat Bubble on selected/*/
.slide-chat.show-msg-true .message--answer.active {
  background: var(--primary-palette-colour);
  color: var(--primary-font-colour);
}
/*/Chat Bubble, the Pointy Part/*/
.slide-chat.show-msg-true .message--answer.active:after {
  border-color: var(--primary-palette-colour) transparent transparent;
}
/*/Expandable List/*/
.slide-expandable-list .item.active .item-button,
.slide-expandable-list .item.active .item-button:after {
  background: var(--secondary-palette-colour);
  color: var(--secondary-font-colour);
}


/* Padronizacao de tipografia dos slides — unifica tamanho e espaçamento (ajustada) */
#slides-view-inner, #slides-view-inner .slide, #slides-view-inner .slide * {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
  font-size: 18px !important;
  line-height: 1.6 !important;
  color: inherit !important;
  -webkit-font-smoothing: antialiased !important;
  -moz-osx-font-smoothing: grayscale !important;
}
#slides-view-inner p, #slides-view-inner span, #slides-view-inner li {
  margin: 0 0 0.75rem 0 !important;
}
#slides-view-inner .text-xl { font-size: 22px !important; font-weight: 700 !important; }
#slides-view-inner .text-lg { font-size: 20px !important; font-weight: 600 !important; }
#slides-view-inner .text-md { font-size: 18px !important; }
#slides-view-inner .text-sm { font-size: 16px !important; }
#lesson-header-title-content, .slide.title .title, .slide.title h1, .slide.title p { font-size: 28px !important; line-height:1.2 !important; }
@media (max-width: 768px) {
  #slides-view-inner, #slides-view-inner .slide, #slides-view-inner .slide * { font-size: 16px !important; }
  #slides-view-inner .text-xl { font-size: 20px !important; }
  #slides-view-inner .text-lg { font-size: 18px !important; }
  #slides-view-inner .text-md { font-size: 16px !important; }
  .slide.title .title, .slide.title h1, #lesson-header-title-content { font-size: 24px !important; }
}
#slides-view-inner li p { margin: 0 !important; padding-bottom: .5rem !important; }
#slides-view-inner .text-sequence span { display:block; margin-bottom: .6rem; }
#slides-view-inner .slide { word-break: break-word; hyphens: auto; overflow-wrap: break-word; }
